1. **存储服务接口 (`IStorageService`)**：
统一异常约定：所有实体变更方法执行成功时均返回解析后的最新对象（如 `Promise<Note>`），在遇到版本冲突、代际失效、实体不存在或配额满时统一通过抛出（Reject）具体的 `SparkNotesError` 派生异常处理，消除“既 resolve 又 throw”的不一致性。

```typescript
export interface StorageQuotaInfo {
  usage: number;           // 已使用字节数
  quota: number;           // 总可用配额字节数
  percentUsed: number;     // 已用百分比 (0~100)
}

export interface PrivateModeCheckResult {
  isPrivate: boolean;      // 是否疑似处于隐私/无痕模式
  confidence: 'low' | 'medium' | 'high' | 'unverified'; // 置信度，诚实声明为 unverified/启发式辅助参考
  details: string;         // 检测诊断信息与局限性说明：现代主流浏览器反指纹安全策略下无标准 Web API，属尽力探测
}

export interface IStorageService {
  init(): Promise<void>;
  close(): Promise<void>;

  // 库代际接口
  getCurrentLibraryGeneration(): Promise<number>;
  bumpLibraryGeneration(): Promise<number>;

  // 便签 CRUD 与严格 CAS 乐观锁（统一成功 resolve Note，冲突/失效 throw 派生异常）
  createNote(note: Omit<Note, 'id' | 'revision' | 'createdAt' | 'updatedAt'>, sessionGeneration: number): Promise<Note>;
  getNoteById(id: string): Promise<Note | null>;
  listNotes(filter?: { status?: NoteStatus; tags?: string[]; isFavorite?: boolean }): Promise<Note[]>;
  saveNote(note: Note, expectedRevision: number, sessionGeneration: number): Promise<Note>; // 统一返回 Promise<Note>，冲突 throw ConcurrentEditConflictError！
  forceSaveNote(note: Note, currentDbRevision: number, sessionGeneration: number): Promise<Note>;

  // 单实体生命周期流转（CAS 递增，携带 sessionGeneration）
  trashNote(id: string, expectedRevision: number, sessionGeneration: number): Promise<Note>;
  restoreNote(id: string, expectedRevision: number, sessionGeneration: number): Promise<Note>;
  unarchiveNote(id: string, expectedRevision: number, sessionGeneration: number): Promise<Note>;
  togglePin(id: string, expectedRevision: number, sessionGeneration: number): Promise<Note>;
  toggleFavorite(id: string, expectedRevision: number, sessionGeneration: number): Promise<Note>;
  hardDeleteNote(id: string, expectedRevision: number, sessionGeneration: number): Promise<void>;

  // 回收区 7 天到期与物理批量清空（单原子事务）
  listExpiredTrashedNotes(retentionMs?: number): Promise<Note[]>; // 默认 retentionMs = 604,800,000 ms
  purgeExpiredTrashedNotes(targetSnapshots: { id: string; revision: number }[], sessionGeneration: number, retentionMs?: number): Promise<{ purgedCount: number }>;
  emptyTrash(targetSnapshots: { id: string; revision: number }[], sessionGeneration: number): Promise<{ purgedCount: number }>;

  // 批量操作（带版本快照与单原子事务回滚保障）
  batchUpdateTags(oldTag: string, newTag: string, targetSnapshots: { id: string; revision: number }[], sessionGeneration: number): Promise<{ affectedCount: number }>;
  batchImportNotes(notes: Note[], mode: 'merge' | 'overwrite', meta?: { appMeta?: AppMeta[]; backupTracker?: BackupTrackerMeta }): Promise<{ inserted: number; updated: number; nextGeneration: number }>;
  clearAllData(): Promise<{ nextGeneration: number }>;

  // 全局元数据实体操作
  getMeta<T>(key: string): Promise<AppMeta<T> | null>;
  setMeta<T>(key: string, value: T): Promise<void>;

  // 浏览器环境感知接口
  requestPersistence(): Promise<boolean>;
  isPersisted(): Promise<boolean>;
  detectPrivateMode(): Promise<PrivateModeCheckResult>; // 启发式尽力探测，明确局限与 unverified 状态
  getStorageQuota(): Promise<StorageQuotaInfo>;
  checkBackupReminderNeeded(): Promise<{ needed: boolean; reason?: 'count_exceeded' | 'time_exceeded'; unbackedChangesCount: number; daysSinceLastBackup: number }>;
}
```

2. **备份服务接口 (`IBackupService`)**：
```typescript
export interface BackupValidationResult {
  valid: boolean;
  errorReason?: string;
  failedRecordId?: string;
  failedField?: string;
  payload?: BackupPayload;
  validationDetails?: {
    schemaCheck: boolean;
    idUniquenessCheck: boolean;
    enumCheck: boolean;
    timestampCheck: boolean;
  };
}

export interface IBackupService {
  exportBackup(options?: { includeTrash?: boolean }): Promise<BackupPayload>;
  exportMarkdownArchive(options?: { includeTrash?: boolean }): Promise<Blob>;
  exportUnsavedDraft(draft: SessionDraft): void; // 独立导出当前未保存草稿文件
  validateBackup(fileContent: string): Promise<BackupValidationResult>;
  importBackup(payload: BackupPayload, mode: 'merge' | 'overwrite'): Promise<{ inserted: number; updated: number; nextGeneration: number }>;
}
```

3. **会话草稿服务接口 (`ISessionDraftService`)**：
```typescript
export interface ISessionDraftService {
  saveDraft(draft: SessionDraft): void;
  getDraft(noteId: string, currentGeneration: number): SessionDraft | null;
  clearDraft(noteId: string, generation: number): void;
  listDraftsForGeneration(generation: number): SessionDraft[];
}
```

4. **检索引擎接口 (`ISearchService`)**：
```typescript
export type ViewScope = 'all' | 'favorites' | 'archived' | 'trashed';

export interface SearchOptions {
  viewScope?: ViewScope; // 严格依视图作用域过滤
}

export interface SearchResult {
  notes: Note[];
  totalMatches: number;
  searchDurationMs: number;
}

export interface ISearchService {
  search(query: string, notes: Note[], options?: SearchOptions): SearchResult;
  highlightText(text: string, query: string): string; // 转义特殊正则符号，返回安全高亮 HTML
}
